Use the active sheet and group rows by Project ID in column H, falling back to Budget ID in column J when H is blank. A project gets “Y” only if its group is linked to a budget and contains at least one technology line, using column L or positive column P. Write plain “Y”/“N” values into Q2:Q11, with “N” for unlinked or non-technology projects.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb.active
vws = vals[ws.title]

def norm_id(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, float):
        if v.is_integer():
            return str(int(v))
        return str(v)
    if isinstance(v, int):
        return str(v)
    s = str(v).strip()
    return s if s else None

def is_linked(v):
    if v is None:
        return False
    if isinstance(v, bool):
        return v
    return str(v).strip().upper() in {"Y", "YES", "TRUE", "1"}

def is_tech(row):
    l_val = vws.cell(row=row, column=12).value  # L: Budget Type
    if l_val is not None and str(l_val).strip().lower() == "technology":
        return True

    p_val = vws.cell(row=row, column=16).value  # P: Technology Revenue
    if isinstance(p_val, (int, float)) and not isinstance(p_val, bool) and p_val > 0:
        return True

    return False

answer_end = 11
scan_end = max(vws.max_row, answer_end)

project_linked = set()
project_tech = set()
row_keys = {}

for r in range(2, scan_end + 1):
    h_val = vws.cell(row=r, column=8).value   # H: Project ID
    j_val = vws.cell(row=r, column=10).value  # J: Budget ID

    key = norm_id(h_val)
    if key is None:
        key = norm_id(j_val)

    row_keys[r] = key
    if key is None:
        continue

    if is_linked(vws.cell(row=r, column=9).value) or norm_id(j_val) is not None:
        project_linked.add(key)

    if is_tech(r):
        project_tech.add(key)

for r in range(2, answer_end + 1):
    key = row_keys.get(r)
    if key is not None and key in project_linked and key in project_tech:
        val = "Y"
    else:
        val = "N"
    ws.cell(row=r, column=17).value = val  # Q

print("sheet:", ws.title)
print("scan_end:", scan_end)
print("Q2:Q11:", [ws.cell(row=r, column=17).value for r in range(2, answer_end + 1)])

wb.save(OUT)
```

